BATCH = 'question-mix-2026'
path = pathlib.Path(__file__).resolve().parent.parent / 'db' / 'seed-questions.json'
pool = [q for q in json.loads(path.read_text()) if q.get('batch') != BATCH]
for cat, d, t, q, o, a, e in Q:
    assert d in ('easy', 'medium', 'hard') and 0 <= a < len(o) and len(set(o)) == len(o), q
    pool.append({"difficulty": d, "category": cat, "topic": t, "batch": BATCH,
                 "question": q, "options": o, "correct": a, "explanation": e})
texts = [x['question'] for x in pool]
assert len(texts) == len(set(texts)), 'duplicate question text'
path.write_text('[\n' + ',\n'.join('  ' + json.dumps(x, ensure_ascii=False, separators=(',', ':')) for x in pool) + '\n]\n')
from collections import Counter
print(len(Q), 'questions added;', dict(Counter((c, d) for c, d, *_ in Q)))
